contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint deposit, uint minSum, uint withdraw) public payable {
        require(address(this).balance >= deposit, "insufficient balance for deposit");

        c.SetMinSum(minSum);
        c.Initialized();
        c.Put{value: deposit}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        require(balanceBefore >= minSum, "balance below MinSum");
        require(balanceBefore >= withdraw, "balance below withdraw amount");
        require(block.timestamp > unlockTimeBefore, "balance still locked");

        uint contractBalanceBefore = address(c).balance;

        c.Collect(withdraw);

        (uint unlockTimeAfter, uint balanceAfter) = c.Acc(address(this));
        require(balanceAfter == balanceBefore - withdraw, "balance did not decrease by withdraw amount");
